const e = $json;
const phoneNumber = e.phoneNumber || null;
if (!phoneNumber) { throw new Error('WF-23 contract violation: phoneNumber missing from WF-02 pre-form envelope'); }
const messageType = e.messageType || null;
const messageContent = e.messageContent ?? null;
const keyword = (messageContent || '').toString().trim().toUpperCase();
const ALIASES = ['STOP','UNSUBSCRIBE','OPT OUT','OPT-OUT','REBOOK'];
const isAlias = ALIASES.indexOf(keyword) !== -1;
const aliasReason = (keyword === 'REBOOK') ? 'rebook_keyword' : 'stop_keyword';
return [{ json: { phoneNumber, contactName: e.contactName || null, messageType, messageContent, messageId: e.messageId || null, phoneNumberFormatted: e.phoneNumberFormatted || phoneNumber, keyword, isAlias, aliasReason } }];

const e = $('Normalize Envelope').first().json;
const messageContent = "We can only read text messages here. To share a file, email it to chinmay_astro@gmail.com with your name and phone number. To get started, please complete the form we sent \u2014 tap Fill Details.";
return [{ json: { phoneNumber: e.phoneNumber, phoneNumberFormatted: e.phoneNumberFormatted || e.phoneNumber, messageType: 'text', messageContent, inboundMessageId: e.messageId || null, userMessage: e.messageContent ?? null } }];

const e = $('Normalize Envelope').first().json;
const isRebook = (e.keyword === 'REBOOK');
const messageContent = isRebook ? "You don't have a previous consultation to rebook yet. To book your first session with Dr. Chinmay Mujumdar, please complete the form we sent \u2014 tap Fill Details." : "You haven't subscribed to anything yet, so there's nothing to opt out of. Whenever you're ready, tap Fill Details on the form we sent to book a consultation with Dr. Chinmay Mujumdar.";
return [{ json: { phoneNumber: e.phoneNumber, phoneNumberFormatted: e.phoneNumberFormatted || e.phoneNumber, messageType: 'text', messageContent, inboundMessageId: e.messageId || null, userMessage: e.messageContent ?? null } }];

const cls = $json;
const n = $('Normalize Envelope').first().json;
let bucket = cls.bucket || 'unrelated';
const confidence = (typeof cls.confidence === 'number') ? cls.confidence : 0;
if (confidence < 0.5) bucket = 'unrelated';
let routeClass;
if (bucket === 'greeting' || bucket === 'wants_consultation') routeClass = 'welcome';
else if (bucket === 'service_related_question') routeClass = 'service';
else if (bucket === 'HELP') routeClass = 'help';
else if (bucket === 'unrelated') routeClass = 'redirect';
else if (bucket === 'garbage' || bucket === 'stop_intent') routeClass = 'silent';
else routeClass = 'block';
const silentReason = (bucket === 'stop_intent') ? 'stop_intent' : 'garbage';
return [{ json: { phoneNumber: n.phoneNumber, contactName: n.contactName, messageType: 'text', messageContent: n.messageContent, messageId: n.messageId, phoneNumberFormatted: n.phoneNumberFormatted, effectiveBucket: bucket, routeClass, silentReason } }];

const e = $('Apply Fail-Open').first().json;
const bodyText = "\ud83d\ude4f Great \u2014 to get started with your Vedic astrology consultation, please complete the form we sent. Tap Fill Details below.";
const interactivePayload = { type: 'flow', header: { type: 'text', text: 'Birth Details Form' }, body: { text: bodyText }, flowId: '2260297164474475', flowCta: 'Fill Details' };
return [{ json: { phoneNumber: e.phoneNumber, phoneNumberFormatted: e.phoneNumberFormatted || e.phoneNumber, messageType: 'interactive', messageContent: bodyText, interactivePayload, inboundMessageId: e.messageId || null, userMessage: e.messageContent ?? null } }];

const e = $json;
const text = e.messageContent || '';
const prompt = "You are a warm, concise assistant for Chinmay Astro, a Vedic astrology consultation service on WhatsApp run by Dr. Chinmay Mujumdar. A prospective customer asked a question. Answer in 1\u20132 short, friendly, factual sentences. Do not invent prices or policies beyond: consultations are \u20b9500 each, paid via GPay, conducted over WhatsApp. If unsure, say the team will help once they share their birth details. Question: " + '"' + text + '"';
const geminiBody = JSON.stringify({ contents: [{ parts: [{ text: prompt }] }], generationConfig: { temperature: 0.3, maxOutputTokens: 200 } });
return [{ json: { ...e, geminiBody } }];

const r = $json;
let answer = '';
try { answer = (((r.candidates || [])[0] || {}).content || {}).parts?.[0]?.text || ''; } catch (err) { answer = ''; }
answer = (answer || '').toString().trim();
const e = $('Apply Fail-Open').first().json;
return [{ json: { ...e, serviceAnswer: answer } }];

const p = $('Parse Service Answer').first().json;
const answer = (p.serviceAnswer || '').trim();
const intro = "To book your consultation, please complete the form below \u2014 tap Fill Details.";
const bodyText = answer ? (answer + '\n\n' + intro) : intro;
const interactivePayload = { type: 'flow', header: { type: 'text', text: 'Birth Details Form' }, body: { text: bodyText }, flowId: '2260297164474475', flowCta: 'Fill Details' };
return [{ json: { phoneNumber: p.phoneNumber, phoneNumberFormatted: p.phoneNumberFormatted || p.phoneNumber, messageType: 'interactive', messageContent: bodyText, interactivePayload, inboundMessageId: p.messageId || null, userMessage: p.messageContent ?? null } }];

